  static List<Post> getPosts({PostCategory? category, String? searchQuery}) {
    var posts = _posts;
    if (category != null) {
      posts = _posts.where((p) => p.category == category).toList();
    }
    if (searchQuery != null && searchQuery.isNotEmpty) {
      posts = posts.where((p) =>
          p.content.toLowerCase().contains(searchQuery.toLowerCase())
      ).toList();
    }
    return List.unmodifiable(posts);
  }

  static Post? getPostById(String id) {
    try {
      return _posts.firstWhere((p) => p.id == id);
    } catch (_) {
      return null;
    }
  }
